ROOT=Path(__file__).resolve().parents[2]; OUT=ROOT/'output'/'pdf'/'PayTimePro-Tax-Setup-User-Guide.pdf'; OUT.parent.mkdir(parents=True,exist_ok=True)
navy=colors.HexColor('#17314d'); copper=colors.HexColor('#9a6d4a'); paper=colors.HexColor('#f4f2ee'); slate=colors.HexColor('#3f5872'); pale=colors.HexColor('#edf1f4'); green=colors.HexColor('#557462'); red=colors.HexColor('#934f49')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleX',parent=styles['Title'],fontName='Helvetica-Bold',fontSize=30,leading=34,textColor=navy,spaceAfter=12))
styles.add(ParagraphStyle(name='SubTitle',parent=styles['Normal'],fontSize=12,leading=18,textColor=slate,spaceAfter=18))
styles.add(ParagraphStyle(name='H1X',parent=styles['Heading1'],fontName='Helvetica-Bold',fontSize=19,leading=23,textColor=navy,spaceBefore=4,spaceAfter=10))
styles.add(ParagraphStyle(name='H2X',parent=styles['Heading2'],fontName='Helvetica-Bold',fontSize=12,leading=15,textColor=copper,spaceBefore=10,spaceAfter=6))
styles.add(ParagraphStyle(name='BodyX',parent=styles['BodyText'],fontSize=9.2,leading=14,textColor=colors.HexColor('#33485c'),spaceAfter=7))
styles.add(ParagraphStyle(name='SmallX',parent=styles['BodyText'],fontSize=7.7,leading=11,textColor=slate))
styles.add(ParagraphStyle(name='Callout',parent=styles['BodyText'],fontSize=8.7,leading=13,textColor=navy,leftIndent=7,rightIndent=7,spaceBefore=4,spaceAfter=4))
styles.add(ParagraphStyle(name='StepNum',parent=styles['BodyText'],fontName='Helvetica-Bold',fontSize=12,textColor=colors.white,alignment=TA_CENTER))

def header_footer(canvas,doc):
    canvas.saveState(); w,h=A4
    canvas.setFillColor(navy); canvas.rect(0,h-12*mm,w,12*mm,fill=1,stroke=0)
    canvas.setFillColor(colors.white); canvas.setFont('Helvetica-Bold',8); canvas.drawString(18*mm,h-7.5*mm,'PayTimePro  |  Payroll Tax Guide')
    canvas.setFillColor(slate); canvas.setFont('Helvetica',7); canvas.drawRightString(w-18*mm,8*mm,f'Page {doc.page}')
    canvas.setStrokeColor(colors.HexColor('#d8dee1')); canvas.line(18*mm,12*mm,w-18*mm,12*mm); canvas.restoreState()

def P(text,style='BodyX'): return Paragraph(text,styles[style])
def callout(title,text,color=copper):
    t=Table([[P(f'<b>{title}</b><br/>{text}','Callout')]],colWidths=[165*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),colors.HexColor('#f1e7de')),('BOX',(0,0),(-1,-1),.8,color),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));return t
def step(n,title,text):
    badge=Table([[P(str(n),'StepNum')]],colWidths=[9*mm],rowHeights=[9*mm]);badge.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),copper),('VALIGN',(0,0),(-1,-1),'MIDDLE')]));
    return Table([[badge,P(f'<b>{title}</b><br/>{text}','BodyX')]],colWidths=[12*mm,151*mm],style=[('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),7)])
def ui_table(title,rows):
    data=[[P(title,'H2X'),'']]+[[P(a,'SmallX'),P(b,'SmallX')] for a,b in rows]
    t=Table(data,colWidths=[56*mm,105*mm]);t.setStyle(TableStyle([('SPAN',(0,0),(1,0)),('BACKGROUND',(0,0),(1,0),navy),('TEXTCOLOR',(0,0),(1,0),colors.white),('BACKGROUND',(0,1),(0,-1),pale),('GRID',(0,1),(-1,-1),.4,colors.HexColor('#d5dde0')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));return t

story=[]
story += [Spacer(1,25*mm),P('PayTimePro','TitleX'),P('Tax Setup, Configuration & Calculator','TitleX'),P('Administrator User Guide  |  Philippine Payroll Withholding','SubTitle'),Spacer(1,7*mm),callout('Purpose','Use this guide to configure an employee payroll profile, maintain BIR withholding tables, calculate statutory deductions and tax, and interpret annualized results.'),Spacer(1,14*mm)]
story += [ui_table('Guide at a glance',[('1. Employee Setup','Define pay basis, salary, frequency, earnings and deductions.'),('2. Tax Configuration','Maintain effective BIR tables and progressive brackets.'),('3. Tax Calculator','Calculate SSS, PhilHealth, Pag-IBIG and withholding.'),('4. Review & controls','Check annualized tax, year-end balance and audit data.')]),Spacer(1,14*mm),P('<b>Audience:</b> Payroll administrators, HR managers, finance reviewers and implementation testers.','BodyX'),P('<b>Version:</b> Prepared August 2026 for the current PayTimePro implementation.','SmallX'),PageBreak()]

story += [P('1. Before you begin','H1X'),P('Sign in with a role that has Payroll and Tax Configuration permissions. The Administrator role receives full access by default. If a menu item is missing, refresh the page or sign out and back in after permissions change.'),callout('Recommended order','Complete Employee Setup first, verify Tax Configuration second, then use the Tax Calculator. The calculator needs both an employee payroll profile and exactly one active tax table matching the pay date and frequency.'),P('Navigation map','H2X'),ui_table('Payroll menu',[('Payroll > Setup','Employee compensation and recurring payroll items.'),('Payroll > Tax Configuration','Effective-dated BIR tables and brackets.'),('Payroll > Tax Calculator','Employee statutory contributions and withholding preview.')]),P('Key concepts','H2X'),P('<b>Gross compensation</b> is pay before statutory deductions and withholding. <b>Taxable compensation</b> excludes qualifying non-taxable pay and employee mandatory contributions. <b>Withholding tax</b> is the period tax deducted by the employer. <b>Annualized tax</b> reconciles calendar-year taxable compensation against tax already withheld.'),PageBreak()]

story += [P('2. Configure an employee payroll profile','H1X'),step(1,'Open Employee Setup','Go to <b>Payroll > Setup</b>.'),step(2,'Choose an employee','Use the employee list to select the person whose payroll profile you want to configure.'),step(3,'Enter compensation','Choose the pay basis and pay frequency, then enter the employee base salary or rate and standard hours per day.'),step(4,'Classify recurring items','Add allowances under Recurring Earnings and other deductions under Recurring Deductions. Mark an earning Taxable when it forms part of taxable compensation.'),step(5,'Save','Select <b>Save setup</b>. The tax calculator cannot run until the payroll profile has been saved.'),Spacer(1,4*mm),ui_table('Compensation fields',[('Pay basis','Monthly salary, daily rate or hourly rate.'),('Base salary/rate','Contractual base amount in Philippine pesos.'),('Pay frequency','Weekly, every two weeks, semi-monthly or monthly.'),('Tax status','Taxable for normal compensation; exempt only when legally supported.'),('Effective date','Date the employee payroll arrangement starts.'),('Taxable earning','Included in compensation subject to withholding.'),('Non-taxable earning','Excluded only when the benefit has a valid statutory basis.')]),callout('Important control','Do not mark an allowance non-taxable merely because the company calls it a benefit. Classification must follow BIR rules and applicable limits.',red),PageBreak()]

story += [P('3. Maintain Tax Configuration','H1X'),step(1,'Open the module','Go to <b>Payroll > Tax Configuration</b>.'),step(2,'Select an official table','PayTimePro preloads BIR 2023-onward Daily, Weekly, Semi-monthly and Monthly configurations.'),step(3,'Review dates and status','Confirm Effective From is January 1, 2023 and the configuration is active. Enter an Effective To date only when a replacement table takes effect.'),step(4,'Review brackets','Each row contains a lower limit, upper limit, predetermined base tax and percentage rate on excess.'),step(5,'Save carefully','Only one active configuration may overlap a frequency and date range. PayTimePro rejects ambiguous active configurations.'),Spacer(1,3*mm),ui_table('Bracket formula',[('Taxable compensation','The amount after non-taxable compensation and mandatory employee contributions.'),('Matching bracket','The row whose lower/upper limits contain taxable compensation.'),('Formula','Base tax + rate x (taxable compensation - lower limit).'),('Biweekly payroll','PayTimePro divides compensation by two, applies the weekly table, then multiplies tax by two.')]),callout('Official tables','Avoid modifying the preloaded BIR tables unless a new BIR issuance requires a replacement. Create an effective-dated configuration instead of overwriting historical rules.'),PageBreak()]

story += [P('4. Calculate employee withholding','H1X'),step(1,'Open Tax Calculator','Go to <b>Payroll > Tax Calculator</b> and choose an employee.'),step(2,'Review tax treatment','Confirm taxable/exempt and Minimum Wage Earner treatment. Employee statutory deductions are calculated from monthly basic salary by the compliance engine.'),step(3,'Enter the pay period','Provide Pay Date and any additional taxable or non-taxable compensation.'),step(4,'Enter year-to-date values','For annualization, enter taxable compensation and tax already withheld before the current period.'),step(5,'Calculate','Select <b>Calculate withholding</b>. Review the table name shown with the results.'),Spacer(1,3*mm),ui_table('Automatic employee contributions',[('SSS','Employee share based on the applicable Monthly Salary Credit; 5% employee share effective January 2025, maximum MSC ₱35,000.'),('PhilHealth','2.5% employee share of monthly basic salary, using the ₱10,000 floor and ₱100,000 ceiling.'),('Pag-IBIG','Normally 2% employee share, using the ₱10,000 Maximum Fund Salary ceiling.'),('Union dues','Added when configured for the employee.')]),callout('Period basis','Contribution schedules are monthly. For non-monthly payroll, ensure company policy allocates monthly contributions to pay periods consistently and reconciles the full monthly liability.'),PageBreak()]

story += [P('5. Benefits and special tax treatment','H1X'),P('The compliance engine separates taxable and non-taxable portions of benefits when category and year-to-date information are supplied.'),ui_table('Common classifications',[('13th month and other benefits','Combined non-taxable ceiling of ₱90,000 per calendar year; excess is taxable.'),('De minimis benefits','Non-taxable only up to the current category ceiling; excess enters taxable supplementary compensation.'),('Minimum Wage Earner','Statutory minimum wage plus qualified holiday, overtime, night differential and hazard pay are exempt; other taxable compensation remains subject to withholding.'),('Managerial fringe benefits','May require separate final Fringe Benefit Tax rather than ordinary compensation withholding.'),('Previous employer','Include current-year taxable compensation and withholding from the prior employer during annualization.')]),P('2026 de minimis examples','H2X'),ui_table('Selected ceilings under RR 29-2025',[('Rice subsidy','₱2,500 per month.'),('Uniform/clothing','₱8,000 per year.'),('Medical assistance','₱12,000 per year.'),('Laundry allowance','₱400 per month.'),('Achievement award','₱12,000 per year, subject to plan conditions.'),('Christmas/anniversary gifts','₱6,000 per year.'),('CBA/productivity incentives','₱12,000 combined per year.'),('Overtime/night meal allowance','Up to 30% of applicable regional basic minimum wage per qualified day.')]),PageBreak()]

story += [P('6. Read and verify the results','H1X'),ui_table('Calculator output',[('Gross compensation','Regular plus supplementary compensation before deductions.'),('Mandatory contributions','Employee SSS, PhilHealth and Pag-IBIG shares, plus configured union dues.'),('Taxable compensation','Amount used to locate the BIR bracket.'),('Withholding this period','Tax that should be deducted for the selected pay period.'),('Annualized tax','Tax calculated on year-to-date plus current taxable compensation using the annual table.'),('Year-end balance','Annualized tax less tax already withheld, including the current-period amount.'),('Configuration','Exact effective BIR table used by the calculation.')]),P('Review checklist','H2X'),P('1. Confirm the employee, pay date and frequency.<br/>2. Confirm the displayed tax configuration is correct.<br/>3. Compare contribution bases with the monthly basic salary.<br/>4. Confirm non-taxable items have documentary support.<br/>5. Review negative year-end balances as potential refunds and positive balances as potential deficiencies.<br/>6. Investigate warnings for overlapping configurations or managerial fringe benefits.'),callout('Do not finalize on preview alone','A preview is a calculation aid. Final payroll should be posted to a payroll run so the calculation snapshot can support reconciliation and reporting.',red),PageBreak()]

story += [P('7. Worked example','H1X'),P('<b>Employee:</b> Monthly salary ₱50,000, paid semi-monthly. Current period has no supplementary compensation. Monthly statutory contributions are allocated by company payroll policy.'),ui_table('Illustrative calculation',[('Semi-monthly regular compensation','₱25,000.00'),('Less employee statutory contributions','Use the allocated SSS, PhilHealth and Pag-IBIG shares for this pay period.'),('Net taxable compensation','Regular compensation less the applicable employee shares and other supported non-taxable amounts.'),('BIR table','2023 onwards - Semi-monthly.'),('Withholding formula','Predetermined tax for the matching bracket plus the prescribed rate on excess.')]),P('If the employee receives a taxable commission, add it as supplementary compensation. If the employee receives 13th-month pay, enter year-to-date benefit information so only the portion beyond the remaining ₱90,000 ceiling becomes taxable.'),callout('Illustration only','Actual withholding depends on the employee contribution allocation, benefits, prior compensation and tax already withheld. Always rely on the calculated values generated from the employee record.'),PageBreak()]

story += [P('8. Troubleshooting and controls','H1X'),ui_table('Message / issue',[('No active tax configuration matches','Activate the correct frequency table and confirm the pay date is within its effective range.'),('Multiple active configurations match','End-date or deactivate the overlapping configuration.'),('Save payroll setup first','Open Payroll > Setup, complete the employee profile and save.'),('Unexpected zero withholding','Check tax status, MWE status, compensation classification, mandatory contributions and bracket limits.'),('Unexpected year-end balance','Verify YTD compensation and tax withheld, including values from a previous employer.'),('Module missing','Refresh permissions, sign out/in, and confirm role access to Payroll and Tax Configuration.')]),P('Operational controls','H2X'),P('- Restrict configuration updates to authorized payroll administrators.<br/>- Do not overwrite historical tax tables; use effective dates.<br/>- Retain evidence supporting non-taxable classifications.<br/>- Reconcile payroll-run totals to BIR 1601-C data monthly.<br/>- Reconcile employee annual totals before preparing BIR Form 2316.<br/>- Have a Philippine payroll or tax professional review production rules and filings.'),PageBreak()]

story += [P('9. Compliance references','H1X'),P('This guide reflects the PayTimePro implementation and official rules available as of August 2026.'),ui_table('Primary references',[('BIR RR 11-2018','Withholding on compensation, periodic tables, cumulative-average method and annualization.'),('BIR Annex E','Revised withholding tables effective January 1, 2023 onward.'),('BIR RR 29-2025','Updated de minimis ceilings effective for 2026.'),('SSS Circular 2024-006','Contribution schedule effective January 2025.'),('PhilHealth Advisory 2025-0002','5% total premium, ₱10,000 floor and ₱100,000 ceiling.'),('Pag-IBIG Circular 460','Maximum Fund Salary increased to ₱10,000 effective February 2024.')]),P('<b>Links</b><br/>BIR: https://www.bir.gov.ph/<br/>SSS: https://www.sss.gov.ph/pay-contribution/<br/>PhilHealth: https://www.philhealth.gov.ph/<br/>Pag-IBIG: https://www.pagibigfund.gov.ph/','SmallX'),Spacer(1,8*mm),callout('Legal notice','This operational guide is not legal or tax advice. Statutory rules can change. Verify new issuances and obtain professional review before filing or remitting payroll taxes.'),Spacer(1,14*mm),P('End of guide','H2X')]

doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=20*mm,bottomMargin=17*mm,title='PayTimePro Tax Setup User Guide',author='PayTimePro')
